// Bundled thermal-ticket font: Noto Naskh Arabic Bold (subset: Latin + Arabic + Kurdish).
// Naskh has thick, well-separated dots that survive low-res thermal printing, unlike the
// system Segoe UI fallback. Tickets render as data: URLs, so the font must be embedded here
// (a relative font path cannot resolve inside a data: URL). Used by ticketStyle() in app.js.
window.NB_TICKET_FONT = 'data:font/woff2;base64,';
